const issueTokenSpend = `-- name: IssueTokenSpend :many
SELECT
  CAST(COALESCE(NULLIF(model, ''), NULLIF(requested_model, ''), '') AS TEXT) AS model,
  CAST(COALESCE(SUM(input_tokens), 0) AS INTEGER) AS input_tokens,
  CAST(COALESCE(SUM(cached_input_tokens), 0) AS INTEGER) AS cached_input_tokens,
  CAST(COALESCE(SUM(output_tokens), 0) AS INTEGER) AS output_tokens,
  CAST(COALESCE(SUM(reasoning_output_tokens), 0) AS INTEGER) AS reasoning_output_tokens,
  CAST(COALESCE(SUM(total_tokens), 0) AS INTEGER) AS total_tokens,
  CAST(COUNT(*) AS INTEGER) AS sessions
FROM codex_sessions
WHERE issue_id = ?1
   OR identifier = ?2
   OR issue_url = ?3
GROUP BY COALESCE(NULLIF(model, ''), NULLIF(requested_model, ''), '')
ORDER BY COALESCE(NULLIF(model, ''), NULLIF(requested_model, ''), '')
`

type IssueTokenSpendParams struct {
	IssueID    sql.NullString `json:"issue_id"`
	Identifier sql.NullString `json:"identifier"`
	IssueURL   sql.NullString `json:"issue_url"`
}

type IssueTokenSpendRow struct {
	Model                 string `json:"model"`
	InputTokens           int64  `json:"input_tokens"`
	CachedInputTokens     int64  `json:"cached_input_tokens"`
	OutputTokens          int64  `json:"output_tokens"`
	ReasoningOutputTokens int64  `json:"reasoning_output_tokens"`
	TotalTokens           int64  `json:"total_tokens"`
	Sessions              int64  `json:"sessions"`
}

func (q *Queries) IssueTokenSpend(ctx context.Context, arg IssueTokenSpendParams) ([]IssueTokenSpendRow, error) {
	rows, err := q.db.QueryContext(ctx, issueTokenSpend, arg.IssueID, arg.Identifier, arg.IssueURL)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []IssueTokenSpendRow{}
	for rows.Next() {
		var i IssueTokenSpendRow
		if err := rows.Scan(
			&i.Model,
			&i.InputTokens,
			&i.CachedInputTokens,
			&i.OutputTokens,
			&i.ReasoningOutputTokens,
			&i.TotalTokens,
			&i.Sessions,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

